using System.ComponentModel;
using System.Runtime.InteropServices;
using LiteLLM.Core;
using Microsoft.VisualStudio.Shell;

namespace LiteLLM.VisualStudio;
// The pkgdef registers this page's GUID under ToolsOptionsPages, and the host asks the package for that GUID when
// the page is opened. Without [Guid] the value is whatever Type.GUID invents for this compilation, so a pkgdef
// generated from an earlier build names a page the package cannot answer for — and Tools → Options shows
// "An error occurred loading this property page" while automation, which names the page, still works.
[Guid("5B68B3C0-4B54-472A-A71A-8424B4244782")]
public sealed class LiteLlmOptionsPage : DialogPage
{
    [Category("Chat"), DisplayName("Request timeout (seconds)"), DefaultValue(120)] public int RequestTimeoutSeconds { get; set; } = 120;
    [Category("Chat"), DisplayName("Enable streaming"), DefaultValue(true)] public bool EnableStreaming { get; set; } = true;
    [Category("Chat"), DisplayName("Continue a dropped stream"), Description("A proxy that times out while the model is quiet, or a server that restarts, cuts a streamed answer short. The text that arrived is kept and the same turn is asked to go on from it, this many times. Each continuation is a new request, so it also spends tokens. Zero keeps the partial answer without asking for the rest."), DefaultValue(2)] public int StreamResumeAttempts { get; set; } = 2;
    [Category("Chat"), DisplayName("Maximum tokens"), Description("Reasoning models spend this budget on thinking before they write anything — keep it generous."), DefaultValue(8192)] public int MaxTokens { get; set; } = 8192;
    [Category("Chat"), DisplayName("Temperature"), DefaultValue(.2)] public double Temperature { get; set; } = .2;
    [Category("Features"), DisplayName("Show reasoning"), DefaultValue(true)] public bool ShowReasoning { get; set; } = true;
    [Category("Features"), DisplayName("Enable safe tool calling"), DefaultValue(true)] public bool EnableToolCalling { get; set; } = true;
    [Category("Features"), DisplayName("Permission mode"), Description("Default permissions observes the individual confirmation settings. Allow all lets every enabled edit and command tool run without prompting."), DefaultValue("default")] public string PermissionMode { get; set; } = "default";
    [Category("Features"), DisplayName("Maximum tool rounds"), Description("Tool rounds before the chat asks whether to keep going. Continuing raises the budget by half, up to 200."), DefaultValue(ChatStateLimits.DefaultToolRounds)] public int MaxToolRounds { get; set; } = ChatStateLimits.DefaultToolRounds;
    [Category("Features"), DisplayName("Enable file editing"), Description("Let the agent create and change files in the open solution. Edits are made in the editor where the file is open, so Ctrl+Z takes them back. Nothing outside the solution can be touched either way."), DefaultValue(true)] public bool EnableFileEditing { get; set; } = true;
    [Category("Features"), DisplayName("Confirm before each edit"), Description("Show the change and wait for Allow before it is written. Off means edits apply straight away, as they do in Visual Studio Code."), DefaultValue(false)] public bool ConfirmEachEdit { get; set; }
    [Category("Features"), DisplayName("Verify the build after edits"), Description("In Agent mode, build the solution after the assistant changes files and hand any errors back to it to fix. The build runs the way Visual Studio's own Build Solution does, so any project type is built the way its project system expects."), DefaultValue(true)] public bool VerifyBuildAfterEdits { get; set; } = true;
    [Category("Features"), DisplayName("Verify the tests after edits"), Description("In Agent mode, run the solution's tests once a build has passed and hand any failures back to the assistant to fix. Off by default: a test run costs far more time than a build. Needs \"Verify the build after edits\", because tests are only meaningful against the assemblies that build just produced."), DefaultValue(false)] public bool VerifyTestsAfterEdits { get; set; }
    [Category("Terminal"), DisplayName("Enable terminal tools"), Description("Let the agent run PowerShell and Command Prompt commands on this computer from the solution directory. Commands are not confined to the solution."), DefaultValue(true)] public bool EnableTerminalTools { get; set; } = true;
    [Category("Terminal"), DisplayName("Confirm before each command"), Description("Show every command and wait for explicit approval before running it."), DefaultValue(true)] public bool ConfirmEachCommand { get; set; } = true;
    [Category("Terminal"), DisplayName("Command timeout (seconds)"), Description("Stop a command after this many seconds. Interactive programs, servers, and watchers are not supported."), DefaultValue(120)] public int CommandTimeoutSeconds { get; set; } = 120;
    [Category("Terminal"), DisplayName("RTK output"), Description("Auto filters supported successful Git terminal output after execution. Off preserves raw output. Requires RTK in Program Files; commands are never rewritten or rerun."), DefaultValue(RtkMode.Auto)] public RtkMode RtkOutputMode { get; set; } = RtkMode.Auto;
    [Category("Context"), DisplayName("Fallback context tokens"), Description("Assumed context capacity when the server omits it; used for estimates, not exact token counting."), DefaultValue(128000)] public int FallbackContextTokens { get; set; } = 128000;
    [Category("Context"), DisplayName("Model context overrides"), Description("Semicolon-separated model-id=tokens or server-model-key=tokens. Example: model-a=32768;model-b=200000."), DefaultValue("")] public string ModelContextOverrides { get; set; } = "";
    [Category("Context"), DisplayName("Compact automatically"), Description("As the conversation nears the model's context ceiling, replace its older part with a structured checkpoint and keep the newest messages verbatim. The decision uses the last response's reported prompt size plus an estimate of what has changed since. Off means only the /compact command compacts, and a server's \"too long\" rejection fails the turn as before."), DefaultValue(true)] public bool AutoCompaction { get; set; } = true;
    [Category("Context"), DisplayName("Keep beside the checkpoint (tokens)"), Description("Newest tokens of the conversation kept word for word beside the checkpoint. Everything older is folded into it. 15000 is the opencode default."), DefaultValue(ContextCompaction.DefaultKeepTokens)] public int CompactionKeepTokens { get; set; } = ContextCompaction.DefaultKeepTokens;
    [Category("Context"), DisplayName("Compaction buffer (tokens)"), Description("Room left free below the model's context window before compacting. 0 uses the larger of 15% of the window and 16000 tokens. A value that would leave no room is ignored."), DefaultValue(0)] public int CompactionBufferTokens { get; set; }
    [Category("Claude Code"), DisplayName("Executable"), Description("Claude Code CLI executable or full path."), DefaultValue("claude")] public string ClaudeExecutable { get; set; } = "claude";
    [Category("Claude Code"), DisplayName("Allowed tools"), Description("Explicit automatic approval for these Claude tools (comma/whitespace-separated rules). File writes and Bash are constrained by the editing, terminal, and confirmation guards; this is separate from the LiteLLM confirmation UI."), DefaultValue("Read,Glob,Grep")] public string ClaudeAllowedTools { get; set; } = "Read,Glob,Grep";
    [Category("Claude Code"), DisplayName("Disallowed tools"), Description("Comma/whitespace-separated Claude tools that must remain unavailable. Claude allowlisting is automatic approval, not the LiteLLM confirmation UI."), DefaultValue("WebFetch,WebSearch")] public string ClaudeDisallowedTools { get; set; } = "WebFetch,WebSearch";
    [Category("Context"), DisplayName("Utility model"), Description("Model used for the extension's own calls, such as summarizing the older part of a long conversation so it can be dropped without losing the thread. Use a small, cheap model here. A model id, or the full key from the model list when two servers offer the same id. Empty uses the model the chat is already talking to."), DefaultValue("")] public string UtilityModelKey { get; set; } = "";
    [Category("MCP"), DisplayName("Enable MCP"), Description("Offer tools from the MCP servers configured in the Dashboard. Servers are added, imported and signed in to on the MCP page, not here."), DefaultValue(true)] public bool EnableMcp { get; set; } = true;
    [Category("MCP"), DisplayName("Auto-approve read-only tools"), Description("A server may mark a tool read-only. When both this and the server's own switch are on, such a tool runs without a card. Destructive and open-world tools are always asked about."), DefaultValue(false)] public bool McpAutoApproveReadOnly { get; set; }
    [Category("MCP"), DisplayName("Allow sampling"), Description("Let a server ask the model for a completion through this extension. It spends the tokens of your configured model, so it is off unless chosen."), DefaultValue(false)] public bool McpAllowSampling { get; set; }
    [Category("MCP"), DisplayName("Allow elicitation"), Description("Let a server ask the user for structured input through a form. Off declines every request."), DefaultValue(true)] public bool McpAllowElicitation { get; set; } = true;
    [Category("MCP"), DisplayName("Allow roots"), Description("Tell a server which directories the open solution covers when it asks."), DefaultValue(true)] public bool McpAllowRoots { get; set; } = true;
    [Category("MCP"), DisplayName("Connect timeout (seconds)"), Description("How long a server may take to start and complete its handshake."), DefaultValue(30)] public int McpConnectTimeoutSeconds { get; set; } = 30;
    [Category("MCP"), DisplayName("Tool timeout (seconds)"), Description("How long one MCP tool call may take before it is reported as timed out."), DefaultValue(120)] public int McpToolTimeoutSeconds { get; set; } = 120;
    [Category("MCP"), DisplayName("Maximum tools per turn"), Description("The most MCP tools offered to a message that names none. Every offered tool is sent as a schema with each request, so a smaller number makes a turn start answering sooner. A tool the message names with # is always offered, however long the server's list is; when the cap cuts the automatic list, the turn says how many were left out."), DefaultValue(McpToolSnapshot.DefaultAutomaticTools)] public int McpMaxToolsPerTurn { get; set; } = McpToolSnapshot.DefaultAutomaticTools;
    [Category("MCP"), DisplayName("Offer tools only when the message asks"), Description("A message that says nothing about MCP is sent with no MCP tool, so its schemas cost the turn nothing and no server list is re-read for it. Name a tool with # in the composer, or mention MCP in the message, to offer them for that turn. Off sends every connected tool with every request, and the model may call one the message never asked for."), DefaultValue(true)] public bool McpToolsOnlyWhenMentioned { get; set; } = true;
    [Category("MCP"), DisplayName("Log level"), Description("The level requested from each server at connect time: debug, info, warning, notice, error, critical, alert, emergency."), DefaultValue("info")] public string McpLogLevel { get; set; } = "info";
    [Category("MCP"), DisplayName("Give Claude only these servers"), Description("Pass --strict-mcp-config so the Claude backend sees exactly the servers shown in the Dashboard and not its own configuration."), DefaultValue(true)] public bool McpStrictClaudeConfig { get; set; } = true;
    [Category("Diagnostics"), DisplayName("Logging level"), DefaultValue("Information")] public string LoggingLevel { get; set; } = "Information";
}
